var _keyOps = stc.NewKey[Ops]("ops")
var _keyTail = stc.NewKey[TailOps]("tail")
var _keyAsyncOps = stc.NewKey[AsyncOps]("async_ops")
var _keyMixed = stc.NewKey[MixedOps]("mixed")

func Agent() stc.Component {
	return stc.Component{
		Name:    "Agent",
		Provide: []stc.Key{_keyOps},
		Apply: func(ctx *stc.Context) (stc.Inverse, error) {
			_revlFrame := newRevlFrame()
			if err := ctx.Effect(func() stc.Inverse {
				return func() error { _revlFrame.runCompensationPhase(); return nil }
			}); err != nil {
				return nil, err
			}
			_implOps := &Agent_ops{ctx: ctx, revlFrame: _revlFrame}
			if _, err := ctx.Provide(_keyOps, Ops(_implOps)); err != nil {
				return nil, err
			}
			return func() error { _revlFrame.commit(); return nil }, nil
		},
	}
}

type Agent_ops struct {
	ctx       *stc.Context
	revlFrame *RevlFrame
}

func (revlSelf *Agent_ops) Run(region string) int64 {
	_revlUi := revlSelf.revlFrame.uiScope("ops.run", true)
	defer _revlUi.exit()
	pane1 := revlUiCross(_revlUi, "read_pane", nil, func() string { return read_pane(region) })
	_ = pane1
	amount := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(pane1, "Amount") })
	_ = amount
	revlUiCrossVoid(_revlUi, "type_amount", &revlCompEntry{key: "clear_amount", method: "clear_amount", run: func() error { clear_amount(); return nil }}, func() { type_amount(amount, "10") })
	pane2 := revlUiCross(_revlUi, "read_pane", nil, func() string { return read_pane(region) })
	_ = pane2
	memo := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(pane2, "Memo") })
	_ = memo
	revlUiCrossVoid(_revlUi, "type_memo", &revlCompEntry{key: "clear_memo", method: "clear_memo", run: func() error { clear_memo(); return nil }}, func() { type_memo(memo, "m") })
	pane3 := revlUiCross(_revlUi, "read_pane", nil, func() string { return read_pane(region) })
	_ = pane3
	approve := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(pane3, "Approve") })
	_ = approve
	revlUiCrossVoid(_revlUi, "actuate", nil, func() { actuate(approve) })
	pane4 := revlUiCross(_revlUi, "read_pane", nil, func() string { return read_pane(region) })
	_ = pane4
	checked := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(pane4, "Approve") })
	_ = checked
	pane5 := revlUiCross(_revlUi, "read_pane", nil, func() string { return read_pane(region) })
	_ = pane5
	note := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(pane5, "Note") })
	_ = note
	revlUiCrossVoid(_revlUi, "type_note", &revlCompEntry{key: "clear_note", method: "clear_note", run: func() error { clear_note(); return nil }}, func() { type_note(note, "n") })
	pane6 := revlUiCross(_revlUi, "read_pane", nil, func() string { return read_pane(region) })
	_ = pane6
	receipt := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(pane6, "Attach") })
	_ = receipt
	saved := revlUiCross(_revlUi, "fetch_receipt", nil, func() string { return fetch_receipt(receipt) })
	_ = saved
	return 1
}

