func (revlSelf *Mixed_mixed) Run(region string) {
	_revlUi := revlSelf.revlFrame.uiScope("mixed.run", true)
	defer _revlUi.exit()
	var _revlWit1 RevlResult[Mark, MarkError]
	_revlWit1 = mark("a")
	if _revlOk1, _revlIsOk1 := _revlWit1.(RevlOk[Mark, MarkError]); _revlIsOk1 {
		result := _revlOk1.Value
		_ = result
		_revlUi.registerWitnessed("unmark", func() (_revlErr error) {
			if revlSelf.revlFrame.committed {
				// item 318 a5a: discharge — the mutation is the deliverable
				// and persists; witness GC'd (out of scope).
				return nil
			}
			defer func() {
				if r := recover(); r != nil {
					revlSelf.revlFrame.recordResidue(RevlTeardownRecord{
						Kind: "restore-residue", CrossingKey: "mark", CrossingMethod: "unmark",
						AttemptedCall: "unmark", AttemptedPhase: 1,
						ErrorType: "panic", ErrorMessage: fmt.Sprint(r),
						Outcome: "failed", Referent: "mark",
						Hint: "the witnessed inverse " + "unmark" + " panicked during abort replay; verify and finish by hand",
					})
				}
			}()
			unmark(result)
			return nil
		})
	}
	var n int64 = revlUiDeclared(_revlUi, put_row("p"), "restore_row", "restore_row", func() error { restore_row(); return nil })
	_ = n
	target := revlUiCross(_revlUi, "locate", nil, func() UiTarget { return locate(region, "Amount") })
	_ = target
	revlUiCrossVoid(_revlUi, "type_amount", &revlCompEntry{key: "clear_note", method: "clear_note", run: func() error { clear_note(); return nil }}, func() { type_amount(target, "10") })
	revlUiCrossVoid(_revlUi, "actuate", nil, func() { actuate(target) })
}

